{
  "vision": "Empower users to create, share, and analyze custom forms effortlessly through an intuitive drag-and-drop interface built with React DnD, storing data securely in PostgreSQL and enabling insights through CSV export and basic analytics.",
  "scope": "The epic covers design and implementation of a web-based form builder with drag-and-drop field creation, form persistence, public sharing via links, response collection, analytics dashboard, and CSV export. Out of scope: advanced analytics, authentication, and form embedding in external sites.",
  "success_criteria": [
    "Users can create and save custom forms with at least six types of fields.",
    "Users can share forms through unique links and export responses as CSV."
  ],
  "user_stories": [
    {
      "id": "US-001",
      "title": "Create drag-and-drop form editor using React DnD",
      "as_a": "form creator",
      "i_want": "to build a form by dragging and arranging available field types",
      "so_that": "I can easily design custom forms without coding",
      "acceptance_criteria": [
        {"given": "a user is on the form editor page", "when": "they drag a field type into the form area", "then": "the new field appears in the form layout"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["frontend", "ReactDnD", "ux"]
    },
    {
      "id": "US-002",
      "title": "Persist created forms in PostgreSQL database",
      "as_a": "system",
      "i_want": "to store form definitions and field configurations",
      "so_that": "users can retrieve, update, or share their saved forms",
      "acceptance_criteria": [
        {"given": "a form is created and saved", "when": "the user refreshes or reopens the editor", "then": "the previously saved form structure is loaded from the database"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["backend", "PostgreSQL", "data-persistence"]
    },
    {
      "id": "US-003",
      "title": "Generate shareable form link for response collection",
      "as_a": "form creator",
      "i_want": "to share my created form via a unique link",
      "so_that": "respondents can fill out the form easily",
      "acceptance_criteria": [
        {"given": "a saved form", "when": "the user clicks 'share form'", "then": "a unique URL is generated for public access to the form"}
      ],
      "priority": "High",
      "story_points": 3,
      "labels": ["sharing", "frontend", "routing"]
    },
    {
      "id": "US-004",
      "title": "Collect and store form responses in PostgreSQL",
      "as_a": "respondent",
      "i_want": "to submit answers to shared forms",
      "so_that": "form creators can view collected data and analyze results",
      "acceptance_criteria": [
        {"given": "a respondent opens a shared form", "when": "they fill and submit the form", "then": "each response is validated and stored in PostgreSQL"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["backend", "PostgreSQL", "data-collection"]
    },
    {
      "id": "US-005",
      "title": "Export collected responses to CSV format",
      "as_a": "form creator",
      "i_want": "to download collected form responses in CSV format",
      "so_that": "I can analyze data offline or in other tools",
      "acceptance_criteria": [
        {"given": "a form has responses stored", "when": "the user clicks 'Export to CSV'", "then": "a CSV file containing all responses is generated and downloaded"}
      ],
      "priority": "Medium",
      "story_points": 3,
      "labels": ["data-export", "backend", "analytics"]
    },
    {
      "id": "US-006",
      "title": "Provide basic analytics dashboard for form responses",
      "as_a": "form creator",
      "i_want": "to view aggregated metrics like total submissions and field-based insights",
      "so_that": "I can understand response trends easily",
      "acceptance_criteria": [
        {"given": "a form with collected responses", "when": "the user opens the analytics dashboard", "then": "summary metrics and visual charts are displayed based on the data"}
      ],
      "priority": "Medium",
      "story_points": 8,
      "labels": ["analytics", "frontend", "data-visualization"]
    }
  ]
}

{
  "summary": "Implementation of a full-stack form builder system with a React DnD frontend and Express/PostgreSQL backend. Includes form creation, persistence, sharing via unique link, response collection, analytics, and CSV export.",
  "code_files": [
    {
      "filename": "src/controllers/formController.js",
      "language": "javascript",
      "description": "Controller handling form creation, saving, retrieval, sharing, and analytics",
      "code": "import Form from '../models/Form.js';
import Response from '../models/Response.js';
import { parse } from 'json2csv';
import { v4 as uuidv4 } from 'uuid';

export const createForm = async (req, res) => {
  try {
    const { name, fields } = req.body;
    const shareId = uuidv4();
    const form = await Form.create({ name, fields, shareId });
    res.status(201).json(form);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create form' });
  }
};

export const getForm = async (req, res) => {
  try {
    const { shareId } = req.params;
    const form = await Form.findOne({ where: { shareId } });
    if (!form) return res.status(404).json({ error: 'Form not found' });
    res.json(form);
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch form' });
  }
};

export const submitResponse = async (req, res) => {
  try {
    const { shareId } = req.params;
    const { answers } = req.body;
    const form = await Form.findOne({ where: { shareId } });
    if (!form) return res.status(404).json({ error: 'Form not found' });
    const response = await Response.create({ formId: form.id, answers });
    res.status(201).json(response);
  } catch (err) {
    res.status(500).json({ error: 'Failed to submit response' });
  }
};

export const getAnalytics = async (req, res) => {
  try {
    const { formId } = req.params;
    const totalResponses = await Response.count({ where: { formId } });
    res.json({ totalResponses });
  } catch (err) {
    res.status(500).json({ error: 'Analytics error' });
  }
};

export const exportCSV = async (req, res) => {
  try {
    const { formId } = req.params;
    const responses = await Response.findAll({ where: { formId } });
    const data = responses.map(r => r.answers);
    const csv = parse(data);
    res.header('Content-Type', 'text/csv');
    res.attachment('responses.csv');
    return res.send(csv);
  } catch (err) {
    res.status(500).json({ error: 'Failed to export CSV' });
  }
};"
    },
    {
      "filename": "src/models/Form.js",
      "language": "javascript",
      "description": "Form model to store form metadata and field definitions",
      "code": "import { DataTypes } from 'sequelize';
import sequelize from '../utils/db.js';

const Form = sequelize.define('Form', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  name: { type: DataTypes.STRING, allowNull: false },
  fields: { type: DataTypes.JSONB, allowNull: false },
  shareId: { type: DataTypes.UUID, allowNull: false, unique: true }
});

export default Form;"
    },
    {
      "filename": "src/models/Response.js",
      "language": "javascript",
      "description": "Model to store form responses",
      "code": "import { DataTypes } from 'sequelize';
import sequelize from '../utils/db.js';
import Form from './Form.js';

const Response = sequelize.define('Response', {
  id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
  formId: { type: DataTypes.INTEGER, allowNull: false, references: { model: Form, key: 'id' } },
  answers: { type: DataTypes.JSONB, allowNull: false }
});

export default Response;"
    },
    {
      "filename": "src/routes/formRoutes.js",
      "language": "javascript",
      "description": "Routes for all form operations including creation, sharing, response collection, analytics, and CSV export",
      "code": "import express from 'express';
import { createForm, getForm, submitResponse, getAnalytics, exportCSV } from '../controllers/formController.js';

const router = express.Router();

router.post('/', createForm);
router.get('/:shareId', getForm);
router.post('/:shareId/submit', submitResponse);
router.get('/:formId/analytics', getAnalytics);
router.get('/:formId/export', exportCSV);

export default router;"
    },
    {
      "filename": "src/utils/db.js",
      "language": "javascript",
      "description": "Database initialization and connection using Sequelize",
      "code": "import { Sequelize } from 'sequelize';
import dotenv from 'dotenv';
dotenv.config();

const sequelize = new Sequelize(process.env.DATABASE_URL, {
  dialect: 'postgres',
  logging: false
});

export default sequelize;"
    },
    {
      "filename": "src/app.js",
      "language": "javascript",
      "description": "Express application setup with routes and middleware",
      "code": "import express from 'express';
import cors from 'cors';
import formRoutes from './routes/formRoutes.js';
import sequelize from './utils/db.js';

const app = express();
app.use(cors());
app.use(express.json());
app.use('/api/forms', formRoutes);

sequelize.sync().then(() => {
  console.log('Database synced');
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
    }
  ],
  "setup_instructions": [
    "npm install",
    "Set DATABASE_URL in .env file",
    "npm run dev"
  ],
  "environment_variables": [
    {
      "name": "DATABASE_URL",
      "description": "PostgreSQL connection string for form builder app",
      "example": "postgresql://user:password@localhost:5432/formbuilderdb"
    }
  ],
  "dependencies": [
    {
      "name": "express",
      "version": "^4.18.0",
      "purpose": "Web server framework"
    },
    {
      "name": "sequelize",
      "version": "^6.32.0",
      "purpose": "ORM for PostgreSQL"
    },
    {
      "name": "pg",
      "version": "^8.11.0",
      "purpose": "PostgreSQL client for Sequelize"
    },
    {
      "name": "json2csv",
      "version": "^6.0.0",
      "purpose": "Convert JSON responses to CSV for export"
    },
    {
      "name": "uuid",
      "version": "^9.0.0",
      "purpose": "Generate unique identifiers for shareable form links"
    },
    {
      "name": "cors",
      "version": "^2.8.5",
      "purpose": "Enable cross-origin requests for frontend integration"
    },
    {
      "name": "dotenv",
      "version": "^16.0.3",
      "purpose": "Load environment variables from .env file"
    }
  ]
}
